import{_ as r,o,c as i,a2 as a}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Memory Providers","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/providers/memory/index.md","filePath":"integrations/providers/memory/index.md","lastUpdated":1788855895000}'),t={name:"integrations/providers/memory/index.md"};function n(s,e,m,l,d,h){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="memory-providers" tabindex="-1">Memory Providers <a class="header-anchor" href="#memory-providers" aria-label="Permalink to &quot;Memory Providers&quot;">​</a></h1><p>Memoh uses a <strong>Memory Provider</strong> to define how a bot stores, retrieves, and manages long-term memory. A bot can bind one memory provider in its <strong>General</strong> tab, and that provider becomes the backend for memory extraction and memory search.</p><h2 id="available-providers" tabindex="-1">Available Providers <a class="header-anchor" href="#available-providers" aria-label="Permalink to &quot;Available Providers&quot;">​</a></h2><p>Memoh supports the following memory providers:</p><ul><li><a href="/integrations/providers/memory/builtin.html">Built-in</a>: The default memory system included with Memoh. Stores a memory graph in PostgreSQL and optionally adds pgvector-backed semantic search when an embedding model is configured.</li><li><a href="/integrations/providers/memory/mem0.html">Mem0</a>: SaaS memory provider via the Mem0 API. Requires an API key.</li><li><a href="/integrations/providers/memory/openviking.html">OpenViking</a>: Self-hosted or SaaS memory provider with its own API.</li></ul><hr><h2 id="basic-flow" tabindex="-1">Basic Flow <a class="header-anchor" href="#basic-flow" aria-label="Permalink to &quot;Basic Flow&quot;">​</a></h2><ol><li>Open the <strong>Memory Providers</strong> page from the sidebar.</li><li>Create a provider instance using one of the supported provider types.</li><li>Configure the provider settings.</li><li>Open a bot&#39;s <strong>General</strong> tab and assign that provider in <strong>Memory Provider</strong>.</li><li>Manage actual memories from the bot&#39;s <strong>Memory</strong> tab.</li></ol><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/integrations/providers/memory/builtin.html">Built-in Memory Provider</a> — Default, self-hosted; PostgreSQL graph plus optional pgvector semantic index.</li><li><a href="/integrations/providers/memory/mem0.html">Mem0 Memory Provider</a> — SaaS via Mem0 API.</li><li><a href="/integrations/providers/memory/openviking.html">OpenViking Memory Provider</a> — Self-hosted or SaaS.</li><li><a href="/guides/memory.html">Bot Memory Management</a> — Manage memory entries after the provider is assigned.</li></ul>',11)])])}const v=r(t,[["render",n]]);export{g as __pageData,v as default};
